// Builds the request that asks Gemini to turn a client call transcript into a job description.
// Gemini may only use what the client actually said. Anything unclear goes into open_questions.

const MODEL = 'gemini-flash-lite-latest';   // same model as the other workflows

const form = $input.first().json;
const company = String(form['Client company'] || '').trim();
const transcript = String(form['Call transcript'] || '').replace(/\r\n/g, '\n').trim();
if (transcript.length < 200) {
  throw new Error('The transcript is too short. Paste the whole call transcript into the form.');
}

const SYSTEM_PROMPT = `You turn a recruiter's call with a client into a job description for a remote role.

RULES
1. Use ONLY what the client said in the transcript. Never invent or guess pay, hours, dates, tools, benefits or requirements.
2. If something was not said, or was left unclear or undecided, set that field to null and add it to open_questions with a short note on what is unclear. Example: "maybe after the holidays, I need to check" means start_date is null and is an open question.
3. must_have = what the client called required, a must, a minimum, or "has to". nice_to_have = what they called a plus, a bonus, nice, preferred, or something "we can train".
4. For every requirement, said_at is the timestamp of the transcript line where the client said it, exactly as written in the transcript (like "00:01:42").
5. The transcript is auto-generated and may misspell tools ("Go Hi Level" is GoHighLevel). Use the correct names.
6. If the client corrected themselves, use the correction.
7. Write for candidates in clear, plain English. Leave out the client's internal staff names and private remarks.
8. search_question: ONE plain-English question to find candidates in a CV database who meet the MUST-HAVE skills, years and languages only. Example: "Who has 3+ years of GoHighLevel?". Do not include nice-to-haves.`;

const str = { type: 'string' };
const strOrNull = { type: ['string', 'null'] };
const requirement = {
  type: 'object', additionalProperties: false, required: ['text', 'said_at'],
  properties: { text: str, said_at: str },
};
const SCHEMA = {
  type: 'object',
  additionalProperties: false,
  required: ['role_title', 'client_company', 'client_contact', 'hires', 'employment_type', 'hours_and_timezone',
    'budget', 'start_date', 'summary', 'responsibilities', 'must_have', 'nice_to_have', 'interview_process',
    'open_questions', 'search_question'],
  properties: {
    role_title: str,
    client_company: str,
    client_contact: strOrNull,          // name and job title of the person on the call
    hires: { type: ['integer', 'null'] },
    employment_type: strOrNull,         // e.g. "Full-time, 40 hours a week"
    hours_and_timezone: strOrNull,
    budget: strOrNull,                  // only if the client said it
    start_date: strOrNull,              // only if the client confirmed it
    summary: str,                       // 2–3 sentences for candidates
    responsibilities: { type: 'array', items: str },
    must_have: { type: 'array', items: requirement },
    nice_to_have: { type: 'array', items: requirement },
    interview_process: strOrNull,
    open_questions: {
      type: 'array',
      items: { type: 'object', additionalProperties: false, required: ['topic', 'note'], properties: { topic: str, note: str } },
    },
    search_question: str,
  },
};

const ai_request = {
  systemInstruction: { parts: [{ text: SYSTEM_PROMPT }] },
  contents: [{ role: 'user', parts: [{ text: `CLIENT COMPANY (from the form): ${company || '(not given)'}\n\nCALL TRANSCRIPT:\n${transcript}` }] }],
  generationConfig: {
    responseMimeType: 'application/json',
    responseJsonSchema: SCHEMA,
    maxOutputTokens: 4000,
  },
};

return [{ json: { ai_request, ai_model: MODEL } }];

// Checks Gemini's job description and lays it out for Slack and the portal.
//   - Every requirement must point to a real timestamp in the transcript, or it is flagged.
//   - Pay, start date, hours or number of hires that were never said become open questions,
//     even if Gemini forgot to list them.
//   - Anything wrong with the answer → ok: false with the reason (nothing is saved).

const form = $('New client call').first().json;
const transcript = String(form['Call transcript'] || '').replace(/\r\n/g, '\n').trim();
const response = $input.first().json;
const clean = (s) => String(s == null ? '' : s).replace(/\s+/g, ' ').trim();
const fail = (problem) => [{ json: { ok: false, problem } }];

// 1. Read Gemini's answer
const cand = (response.candidates || [])[0];
if (!cand) {
  const blocked = response.promptFeedback && response.promptFeedback.blockReason;
  return fail(blocked ? `Gemini refused the request (${blocked}).` : 'Gemini sent an empty answer.');
}
if (cand.finishReason && cand.finishReason !== 'STOP') {
  return fail(cand.finishReason === 'MAX_TOKENS' ? 'The answer was too long and got cut off.' : `Gemini stopped early (${cand.finishReason}).`);
}
let jd;
try {
  const text = ((cand.content && cand.content.parts) || [])
    .filter((p) => typeof p.text === 'string' && !p.thought).map((p) => p.text).join('').trim()
    .replace(/^```(?:json)?\s*|\s*```$/g, '');
  jd = JSON.parse(text);
} catch (e) {
  return fail("Gemini's answer was not readable.");
}
if (!clean(jd.role_title)) return fail('Gemini could not find a job title in the transcript.');

// 2. Tidy the fields
const list = (a) => (Array.isArray(a) ? a.map(clean).filter(Boolean) : []);
const reqs = (a) => (Array.isArray(a) ? a : [])
  .map((r) => ({ text: clean(r && r.text), said_at: clean(r && r.said_at) }))
  .filter((r) => r.text);
const orNull = (v) => (clean(v) ? clean(v) : null);

jd = {
  role_title: clean(jd.role_title),
  client_company: clean(form['Client company']) || clean(jd.client_company) || 'Unknown client',
  client_contact: orNull(jd.client_contact),
  hires: Number.isInteger(jd.hires) && jd.hires > 0 ? jd.hires : null,
  employment_type: orNull(jd.employment_type),
  hours_and_timezone: orNull(jd.hours_and_timezone),
  budget: orNull(jd.budget),
  start_date: orNull(jd.start_date),
  summary: clean(jd.summary),
  responsibilities: list(jd.responsibilities),
  must_have: reqs(jd.must_have),
  nice_to_have: reqs(jd.nice_to_have),
  interview_process: orNull(jd.interview_process),
  open_questions: (Array.isArray(jd.open_questions) ? jd.open_questions : [])
    .map((q) => ({ topic: clean(q && q.topic), note: clean(q && q.note) })).filter((q) => q.topic || q.note),
  search_question: clean(jd.search_question),
};

// 3. Grounding check: each requirement's timestamp must exist in the transcript
const stamps = new Set((transcript.match(/\b\d{1,2}:\d{2}(?::\d{2})?\b/g) || []));
const unsourced = [];
for (const r of [...jd.must_have, ...jd.nice_to_have]) {
  if (!r.said_at || !stamps.has(r.said_at)) { unsourced.push(r.text); r.said_at = '⚠️ not in the transcript'; }
}
if (unsourced.length) {
  jd.open_questions.push({ topic: 'Check these requirements', note: `No matching line in the transcript for: ${unsourced.join('; ')}. Confirm them with the client.` });
}

// 4. Key details that were never said become open questions (if Gemini didn't already list them)
const KEY = [
  ['budget', 'Budget', /budget|pay|salary|rate|compensation/i],
  ['start_date', 'Start date', /start/i],
  ['hours_and_timezone', 'Hours', /hour|time ?zone|schedule|shift|weekend/i],
  ['hires', 'Number of hires', /hire|how many|headcount|people/i],
];
for (const [field, topic, pattern] of KEY) {
  if (jd[field] == null && !jd.open_questions.some((q) => pattern.test(q.topic + ' ' + q.note))) {
    jd.open_questions.push({ topic, note: 'Not confirmed on the call.' });
  }
}
if (!jd.must_have.length) jd.open_questions.push({ topic: 'Requirements', note: 'No clear must-have requirements were found in the call.' });

// 5. The job description as one readable text (for the portal)
const bullets = (a) => a.map((x) => `• ${typeof x === 'string' ? x : x.text}`).join('\n');
const or = (v) => v || 'Not confirmed yet';
const jd_text = [
  `${jd.role_title}`,
  `Client: ${jd.client_company}${jd.hires ? ` · ${jd.hires} hire${jd.hires > 1 ? 's' : ''}` : ''}`,
  '',
  jd.summary,
  '',
  'What you will do', bullets(jd.responsibilities),
  '',
  'Must have', bullets(jd.must_have),
  ...(jd.nice_to_have.length ? ['', 'Nice to have', bullets(jd.nice_to_have)] : []),
  '',
  `Type: ${or(jd.employment_type)}`,
  `Hours: ${or(jd.hours_and_timezone)}`,
  `Pay: ${or(jd.budget)}`,
  `Start: ${or(jd.start_date)}`,
  ...(jd.interview_process ? [`Interview: ${jd.interview_process}`] : []),
].join('\n');

// 6. The Slack approval message (Slack allows ~3000 characters per message block)
const slackList = (a, withSource) => a.map((r) => `• ${r.text}${withSource && r.said_at ? `  _(${r.said_at})_` : ''}`).join('\n');
let slack_text = [
  `📝 *New job description · waiting for your approval*`,
  `*${jd.role_title}* · ${jd.client_company}${jd.hires ? ` · ${jd.hires} hire${jd.hires > 1 ? 's' : ''}` : ''}`,
  jd.summary,
  '',
  '*Must have*', slackList(jd.must_have, true) || '• (none found)',
  ...(jd.nice_to_have.length ? ['*Nice to have*', slackList(jd.nice_to_have, true)] : []),
  '',
  `*Type:* ${or(jd.employment_type)}`,
  `*Hours:* ${or(jd.hours_and_timezone)}`,
  `*Pay:* ${or(jd.budget)}`,
  `*Start:* ${or(jd.start_date)}`,
  ...(jd.open_questions.length ? ['', '⚠️ *Unclear or missing (check with the client):*', ...jd.open_questions.map((q) => `• *${q.topic}:* ${q.note}`)] : []),
  '',
  `🔎 Shortlist search: _${jd.search_question || '(none)'}_`,
  `Nothing is shared with the client or candidates until you approve.`,
].join('\n');
if (slack_text.length > 2900) slack_text = slack_text.slice(0, 2850) + '\n… (full job description in the portal)';

return [{
  json: {
    ok: true,
    role: {
      client_company: jd.client_company,
      client_contact: jd.client_contact,
      role_title: jd.role_title,
      hires: jd.hires,
      transcript,
      jd,
      jd_text,
      open_questions: jd.open_questions,
      search_question: jd.search_question,
    },
    slack_text,
  },
}];
